def nested_parens(parens: str) -> int:
    """ Input to this function is a string representing nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> nested_parens('(()()) ((())) () ((())()())')
    2
    """
    if parens != '':
        if parens[0] == '(':
            parens = parens[1:]
        if parens[-1] == ')':
            parens = parens[:-1]
        nested_parens_iter = parse_nested_parens(parens)
        if len(nested_parens_iter) == 1 and nested_parens_iter[0] == 0

    list_of_groups = paren_string.split(' ')

    max_deepest_levels = []

    for group in list_of_groups:
        # If there is just one element, that means it doesn't contain any parens so we return 0 to denote no nesting
        if len(group) <= 1:
            max_deepest_levels.append(0)

        # Otherwise, we want to split the group on spaces
        # Each of the subgroups will have a value between 0 and 2
        # The one with the greatest value is the one that corresponds with the maximum nesting
        max_deepest_level = 0
        for paren_group in group.split(' '):
            if paren_group == '':
                max_deepest_level = max(max_deepest_level, 1)
            else:
                if not paren_group.startswith('['):
                    max_deepest_level = max(max_deepest_level, 2)

        max_deepest_levels.append(max_deepest_level)

    return max_deepest_levels


def parse_nested_parens_with_count(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the

    paren_str = paren_string.strip()
    assert paren_str, 'No paren groups found'
    paren_groups = paren_str.split(' ')  # list of strings

    def _get_depth(paren_group):
        """ Input a single paren group. Return its maximum depth of nesting."""
        if not paren_group:
            return -1

        max_depth = -1
        for paren in paren_group:
            if '(' in paren:
                max_depth = max(max_depth, _get_depth(paren))
            if ')' in paren:
                max_depth = max(max_depth, _get_depth(paren[1:]))
                return max_depth + 1
        return max_depth

    answer = []
    for paren in paren_groups:
        answer.append(_get_depth(paren))
    return answer


