def var(numbers: List[float]) -> float:
    """ Return the variance of a given list of numbers, which are expected
    to all be of the same type and will be nonempty.
    Variance is the average of the squared differences from the mean.
    >>> var([1.0, 2.0, 3.0, 4.0])
    1.0
    """
    sum = 0
    for num in numbers:
        sum += ((num - mean(numbers)) ** 2)
    return round(sum / len(numbers), 2)


def std_dev(numbers: List[float]) -> float:

    if len(numbers) == 0:
        return 0.0

    numbers_sum = 0
    mean = sum(numbers) / len(numbers)

    for num in numbers:
        numbers_sum += abs(num - mean)

